identity_check.command:
node --input-type=module <<'NODE'
import assert from 'node:assert/strict';
import {readFileSync} from 'node:fs';
import {artifactDigest} from './scripts/remediation/board.mjs';
import {createHash} from 'node:crypto';
import {runInNewContext} from 'node:vm';
import {build} from 'esbuild';
const sha=x=>createHash('sha256').update(x).digest('hex');
const dir='docs/remediation/evidence/W01.02/';
const manifest=JSON.parse(readFileSync(dir+'artifact-manifest-v4.json'));
const previous=JSON.parse(readFileSync(dir+'artifact-manifest-v3.json'));
assert.equal(sha(readFileSync(dir+'artifact-manifest-v3.json')),'a6967eb8b52ed01345a6fea5e38c6e3a12c2788aa61ac790752213ab0e195a9c');
assert.equal(manifest.contract_digest,previous.contract_digest);
assert.equal(manifest.contract_digest,'cfcf38ed052aa9348d113240d6bdaff626e811e4938033077025a1c2e0ffaeb5');
assert.equal(manifest.digest,artifactDigest(manifest));
assert.equal(manifest.digest,'a4aec28dea2bf9c8709bd5c00a2a70f93101b898acba9c4cd9a3298cc42f0505');
for(const file of manifest.files)assert.equal(sha(readFileSync(file.path)),file.sha256,file.path);
for(const file of previous.files)assert.deepEqual(manifest.files.find(f=>f.path===file.path),file);
const added=manifest.files.filter(f=>!previous.files.some(p=>p.path===f.path));
assert.deepEqual(added,[{path:'src/middleware/rate-limiter.ts',sha256:'2ecf40ca0f70d7b0e6848c1c11927a22896db9e295320db60e40d803d5510fe6',role:'source'}]);
const test=readFileSync('src/index.api-boundary.test.ts','utf8');
const context={JSON};
for(const name of ['SECRET','PRIVATE','CACHE_KEY','STORAGE_KEY','STATE_KEY'])context[name]=runInNewContext(test.match(new RegExp('const '+name+" = ('[^']*');"))[1]);
const wrapper=test.match(/const wrapper = (`[\s\S]*?`);\n\nlet runtime/);
const banner=test.match(/banner: \{ js: (`[\s\S]*?`) \},/);
const originalSources={};
const result=await build({stdin:{contents:runInNewContext(wrapper[1],context),resolveDir:process.cwd(),sourcefile:'w0102-runtime.ts',loader:'ts'},bundle:true,write:false,metafile:true,format:'esm',platform:'browser',target:'es2022',conditions:['workerd','worker','browser'],external:['cloudflare:*','node:*'],alias:{path:'node:path','node:os':'unenv/node/os'},banner:{js:runInNewContext(banner[1])},logLevel:'silent',plugins:[{name:'original',setup(b){b.onResolve({filter:/^(\.\/src\/index\.ts|@\/routes\/api)$/},a=>({path:a.path==='./src/index.ts'?'index':'api',namespace:'w0102-before'}));b.onLoad({filter:/.*/,namespace:'w0102-before'},a=>{const contents=readFileSync(dir+'before-'+a.path+'.ts.txt','utf8').slice(0,-1);originalSources[a.path]=sha(contents);return {contents,loader:'ts',resolveDir:process.cwd()};});}}]});
const inputs=Object.keys(result.metafile.inputs).sort();
const physical=inputs.filter(p=>p!=='w0102-runtime.ts'&&!p.startsWith('w0102-before:'));
const uncovered=physical.filter(p=>!manifest.files.some(f=>f.path===p)).map(path=>({path,sha256:sha(readFileSync(path))}));
const mismatches=physical.flatMap(path=>{const f=manifest.files.find(f=>f.path===path);return f&&sha(readFileSync(path))!==f.sha256?[path]:[];});
assert.deepEqual(uncovered,[]);
assert.deepEqual(mismatches,[]);
assert.deepEqual(originalSources,{index:'a9ca5ae49c3741d9375bd0245c7e377bfd779021055df9d90671b0f580f9f4f1',api:'905f2512b23e6639441067a45864fe25634b3fbf2d9fc977b34370fbd90dca58'});
console.log(JSON.stringify({at:new Date().toISOString(),result:'pass',manifestDigest:manifest.digest,manifestFileSha256:sha(readFileSync(dir+'artifact-manifest-v4.json')),files:manifest.files.length,unchangedPriorFiles:previous.files.length,added,contractUnchanged:true,inputCount:inputs.length,physicalInputs:physical.length,inputPathsSha256:sha(JSON.stringify(inputs)),bundleSha256:sha(result.outputFiles[0].contents),uncovered,mismatches,originalSources},null,2));
NODE
